-- Module 11 (Phase 7A): publishing support for timetable versions.
--
-- Purely additive: four columns and one foreign key on "timetable_versions", one partial unique index and one CHECK
-- constraint. No table is created or dropped, no existing column or row is altered, and "timetable_entries" is untouched.
--
-- Part 1 is generated by `prisma migrate diff`. Part 2 is hand-written: Prisma's schema language cannot express a partial
-- unique index or a CHECK constraint (as in the earlier migrations).

-- ===== Part 0: preflight =====
-- Phase 1-6 can only create DRAFT versions, so nothing else may exist. If a row were PUBLISHED or ARCHIVED it could not satisfy
-- the new status/metadata CHECK (it has no publish timestamps) and would have to be reviewed by a person: stop instead of
-- guessing, and change nothing.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "timetable_versions" WHERE "status" <> 'DRAFT') THEN
    RAISE EXCEPTION 'timetable_versions contains non-DRAFT rows; review them before applying this migration';
  END IF;
END $$;

-- ===== Part 1: generated =====

-- AlterTable
ALTER TABLE "timetable_versions" ADD COLUMN     "archivedAt" TIMESTAMPTZ(3),
ADD COLUMN     "publishedAt" TIMESTAMPTZ(3),
ADD COLUMN     "publishedById" TEXT,
ADD COLUMN     "revision" INTEGER NOT NULL DEFAULT 1;

-- AddForeignKey
ALTER TABLE "timetable_versions" ADD CONSTRAINT "timetable_versions_publishedById_fkey" FOREIGN KEY ("publishedById") REFERENCES "admins"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ===== Part 2: hand-written constraints =====

-- At most ONE published version per academic year, enforced by PostgreSQL itself. An ARCHIVED or DRAFT version does not count.
CREATE UNIQUE INDEX "timetable_versions_one_published_per_year"
  ON "timetable_versions" ("academicYearId")
  WHERE "status" = 'PUBLISHED';

-- The status and the publish metadata always agree:
--   DRAFT      never published, never archived
--   PUBLISHED  published, not archived
--   ARCHIVED   was published, then archived
ALTER TABLE "timetable_versions"
  ADD CONSTRAINT "timetable_versions_status_metadata_check" CHECK (
    ("status" = 'DRAFT'     AND "publishedAt" IS NULL     AND "archivedAt" IS NULL)
 OR ("status" = 'PUBLISHED' AND "publishedAt" IS NOT NULL AND "archivedAt" IS NULL)
 OR ("status" = 'ARCHIVED'  AND "publishedAt" IS NOT NULL AND "archivedAt" IS NOT NULL)
  );

-- The optimistic-concurrency token starts at 1 and only grows.
ALTER TABLE "timetable_versions"
  ADD CONSTRAINT "timetable_versions_revision_check" CHECK ("revision" >= 1);
